# ==============================================================================
# The manuscript astrocyte figure panels (Fig1B, Fig1D, Fig1E, S12a, S12b, S13a,
# S15), extracted from 06-astrocyte_analysis/astrocyte_analysis.Rmd so they can be
# regenerated by command.
#
# Method
#   The Rmd rebuilds the astrocyte object (subset, re-normalise, Harmony,
#   re-cluster, tSNE), and Louvain/Harmony do not guarantee identical cluster
#   numbering, so re-rendering it would invalidate the cluster-based
#   subcluster_labels. Here the clustering and embedding are taken as given from
#   the labelled object (donor 1040's VST astrocytes removed), and only the figure
#   code is re-run. Fixes to the notebook's figure chunks are marked REVISION
#   inline, with the Rmd line they replace. Main changes from the published panels:
#   Fig1E uses donor-paired pseudobulk DE (astro_subtype_de) instead of cell-level
#   Wilcoxon, up-regulated genes only, and the tested genes as GO background;
#   Fig1B and S15 use pseudobulk DE (DEG rule: detected in >5% of nuclei in either
#   group, FDR < 0.05, |logFC| > 0.25 for Fig1B) with the up/down selection signs
#   corrected.
#
#   Panel inputs:
#     object only            Fig1D subtype tSNE + 8-gene feature grids; Fig1E GO
#                            heatmap for Reactive-PWH; S12b subtype proportion by
#                            donor; S13a inflammatory dot plot
#     scorch_meta            S12a astrocyte percentage by region; needs
#                            combined_v3_cell_metadata.csv dumped from the
#                            1040-filtered combined object (the script stops otherwise)
#     cross-region DE        Fig1B GO enrichment, PWH and PWoH astrocytes (Rmd:262-405);
#                            S15 per-cell-type GO heatmaps, down and up (Rmd:747-908),
#                            or per-subtype PWH vs PWoH DE with --s15-de subtype.
#                            These two do not load the astrocyte object.
#   Panels whose inputs are missing are skipped with a message.
#
# Inputs   OUT_ROOT/06-astrocyte_analysis/data/astro_all_clusters_labeled_no1040vst.RDS
#          OUT_ROOT/01-Regional_data_processing/combined/data/combined_v3_cell_metadata.csv
#          cross-region DE table from xr_de_file() (revision/config/paths.R)
#          OUT_ROOT/06-astrocyte_analysis/subtype_condition_de/astro_subtype_PWH_vs_PWoH.csv
# Outputs  OUT_ROOT/06-astrocyte_analysis/figures/<panel><suffix>.png/.pdf
#          OUT_ROOT/06-astrocyte_analysis/figures/tables/ (enrichment tables)
#
# Usage: revision/docker/run.sh revision/tools/astro_manuscript_figures.R
#          [--in <file>] [--suffix _x] [--only Fig1B,S15] [--s15-de celltype|subtype]
# ==============================================================================

suppressPackageStartupMessages({
  library(Seurat); library(ggplot2); library(ggpubr); library(dplyr); library(tidyr)
  library(clusterProfiler); library(org.Hs.eg.db); library(enrichplot); library(patchwork)
})

source(file.path(Sys.getenv("SCORCH_REPO", "."), "revision/config/paths.R"))
for (f in c("astro_cluster_features", "astro_figure_inputs", "astro_composition_donor",
            "astro_subtype_de_donor", "astro_reviewer_figures"))
  source(file.path(file.path(SCORCH_REPO, "revision/tools"), paste0(f, ".R")))

args   <- commandArgs(trailingOnly = TRUE)
getarg <- function(f, d) { i <- match(f, args); if (is.na(i) || i == length(args)) d else args[i + 1] }

rerun_setup("06-astrocyte_analysis", subdirs = c("data", "figures"))

.cands <- c(
  if (nzchar(getarg("--in", ""))) file.path("./data", getarg("--in", "")) else NA_character_,
  "./data/astro_all_clusters_labeled_no1040vst.RDS",
  "./data/astro_all_clusters_labeled.RDS"
)
IN <- .cands[!is.na(.cands) & file.exists(.cands)][1]
if (is.na(IN)) stop("no astrocyte object found under ./data")
if (!grepl("no1040", IN))
  warning("[astro-ms] ", basename(IN), " still contains donor 1040's VST cells",
          immediate. = TRUE)

SFX  <- getarg("--suffix", if (grepl("no1040", IN)) "_no1040vst" else "")
ONLY <- strsplit(getarg("--only", ""), ",")[[1]]
want <- function(p) !length(ONLY) || p %in% ONLY

message("[astro-ms] input : ", IN)
message("[astro-ms] suffix: ", if (nzchar(SFX)) SFX else "(none)")

## The ~1 GB object is needed only by the object panels. Fig1B, S15 and S12a
## read tables, so `--only Fig1B,S15` does not load it.
NEED_OBJ <- any(vapply(c("Fig1D", "Fig1E", "S12b", "S13a"), want, logical(1)))
if (NEED_OBJ) {
  obj <- readRDS(IN)

  ## The Rmd's "clean" subset: the seven real astrocyte subtypes, dropping the
  ## Oligo and Endo-Astro contamination clusters. (Rmd line 206.)
  CLEAN_SUBTYPES <- c("Homeostatic", "Reactive", "Reactive-PWH", "Signaling",
                      "Synaptic", "Micro-Astro", "Mural-Astro")
  Idents(obj) <- "subcluster_labels"
  present <- intersect(CLEAN_SUBTYPES, unique(as.character(obj@meta.data$subcluster_labels)))
  clean_scorch_astro <- subset(obj, idents = present)
  message("[astro-ms] clean subset: ", ncol(clean_scorch_astro), " cells, ",
          length(present), " subtypes")
} else message("[astro-ms] no object panels requested - astrocyte object not loaded")

## save_fig() writes PNG + PDF into 06-astrocyte_analysis/figures; wrap it so
## every name carries the suffix.
sfig <- function(p, name, ...) save_fig(p, paste0(name, SFX), ...)

ran <- character(0); skipped <- character(0)

## ---- Fig1D: subtype tSNE + feature grids -------------------------------------
if (want("Fig1D")) tryCatch({
  message("\n=================== Fig1D ===================")
  ## REVISION: the shared subtype palette (ASTRO_SUBTYPE_COLOURS, "pastel_blue",
  ##   which keeps Signaling distinct from Reactive-PWH) and large bold labels on
  ##   white boxes, no title, instead of DimPlot's default hues and small labels.
  lv <- intersect(names(ASTRO_SUBTYPE_COLOURS), unique(as.character(clean_scorch_astro$subcluster_labels)))
  clean_scorch_astro$subcluster_labels <- factor(as.character(clean_scorch_astro$subcluster_labels), levels = lv)
  dim_plot <- DimPlot(object = clean_scorch_astro, reduction = "tsne",
                      group.by = "subcluster_labels", cols = ASTRO_SUBTYPE_COLOURS[lv],
                      raster = FALSE, shuffle = TRUE, pt.size = 0.3) +
    theme_void() + NoLegend() + theme(plot.title = element_blank())
  dim_plot <- LabelClusters(dim_plot, id = "subcluster_labels", repel = TRUE, size = 6.5,
                            fontface = "bold", colour = "black", box = TRUE,
                            fill = scales::alpha("white", 0.85), segment.colour = "grey30",
                            segment.size = 0.3, max.overlaps = Inf)

  ## REVISION (Rmd:431): reduction must be given. Without it Seurat picks by its
  ## default order (umap, tsne, pca) and draws on `umap`, which this object
  ## inherited from seurat_combined_v2 - an embedding over all 641,923 cells of
  ## every type, not over the astrocytes. `tsne` is the astrocyte-specific one.
  feature_plots <- FeaturePlot(
    object = clean_scorch_astro,
    features = c("GFAP","CD44","AQP4","OSMR","SERPINA3","CHI3L1","SYT1","GRIA1"),
    reduction = "tsne",
    ## draw expressing cells ON TOP of the zeros - with ~73k sparse nuclei the
    ## positive cells are otherwise buried under the grey ones
    order = TRUE, combine = FALSE)

  FEATURE_PAL <- "grey_red"
  ## gene names 26 pt bold for legibility in the assembled figure
  ## coord_fixed: the 2x2 top and 1x4 bottom grids would otherwise stretch the
  ##   same tSNE into two different shapes; a fixed 1:1 aspect keeps it true
  feature_plots <- lapply(feature_plots, function(p)
    p + feature_scale(FEATURE_PAL) + theme_void() + coord_fixed() +
      theme(legend.position = "none",
            plot.title = element_text(hjust = 0.5, face = "bold", size = 26)))

  feature_grid_top    <- wrap_plots(feature_plots[1:4], ncol = 2)
  feature_grid_bottom <- wrap_plots(feature_plots[5:8], ncol = 4)
  ## full grid 2 x 4: with fixed aspect the 2x2-over-1x4 stack leaves the top
  ##   block small in white space; top / bottom files are kept for assembly
  feature_grid        <- wrap_plots(feature_plots, ncol = 4)

  sfig(dim_plot,            "Fig1D_astro_subtype_tsne",  width = 10, height = 8)
  sfig(feature_grid_top,    "Fig1D_feature_grid_top",    width = 8,  height = 8)
  sfig(feature_grid_bottom, "Fig1D_feature_grid_bottom", width = 14, height = 4)
  sfig(feature_grid,        "Fig1D_feature_grid",        width = 14, height = 8)
  ran <- c(ran, "Fig1D")
}, error = function(e) { message("[astro-ms] Fig1D FAILED: ", conditionMessage(e))
                         skipped <<- c(skipped, "Fig1D (error)") })

## ---- Fig1E: GO heatmap for Reactive-PWH --------------------------------------
if (want("Fig1E")) tryCatch({
  message("\n=================== Fig1E ===================")
  ## REVISION (Rmd:484): the published code used a cell-level FindMarkers
  ## Wilcoxon, which is not donor-aware. astro_subtype_de() pseudobulks each donor
  ## twice - their cells of the subtype, and their remaining astrocytes - so the
  ## replicates are people, not nuclei.
  sde <- astro_subtype_de(clean_scorch_astro, subtype = "Reactive-PWH")
  geneList <- setNames(sde$de$logFC, sde$de$gene)

  ## REVISION (Rmd:497): select genes that mark the population - up only. The
  ## published abs(logFC) > 1.5, applied to the pseudobulk result, gives mostly
  ## down genes and describes what Reactive-PWH lacks.
  FIG1E_LFC <- 0.5
  gene <- sde$de$gene[sde$de$FDR < 0.05 & sde$de$logFC > FIG1E_LFC]
  message("[Fig1E] up-regulated marker genes into enrichGO: ", length(gene),
          "  (FDR < 0.05, logFC > ", FIG1E_LFC, ")")
  if (!length(gene)) stop("no up-regulated marker genes passed the cut")

  ## REVISION: background = the genes actually tested, i.e. those passing
  ##   filterByExpr in the paired astrocyte pseudobulks (sde$de, ~19k), which are
  ##   also the genes expressed in astrocytes. The published call set no universe,
  ##   so enrichGO compared against every annotated gene in the genome, which
  ##   inflates enrichment for any astrocyte-expressed pathway.
  universe <- unique(sde$de$gene)
  message("[Fig1E] enrichGO universe: ", length(universe), " genes tested in the paired DE")
  ego <- enrichGO(gene = gene, keyType = "SYMBOL", OrgDb = org.Hs.eg.db, ont = "BP",
                  universe = universe,
                  pAdjustMethod = "BH", pvalueCutoff = 0.01, qvalueCutoff = 0.05,
                  readable = TRUE)
  message("[Fig1E] GO terms at p.adjust < 0.01: ", nrow(as.data.frame(ego)))
  dir.create(file.path(ASTRO_FIG_DIR(), "tables"), recursive = TRUE, showWarnings = FALSE)
  utils::write.csv(as.data.frame(ego), file.path(ASTRO_FIG_DIR(), "tables",
                   paste0("Fig1E_GO_Reactive_PWH", SFX, ".csv")), row.names = FALSE)

  N_TERMS <- 10; N_SHOW <- 40
  ## With the tested-gene universe the top 10 terms are mostly near-duplicates
  ##   (angiogenesis / vasculature variants, ECM, GBP1/GBP2-only "killing of /
  ##   disruption of cells in another organism"). Near-duplicates are merged with
  ##   the same rule as the Fig3 pathway panels: clusterProfiler::simplify, Wang
  ##   similarity > 0.6, the best-p term of each group kept. The unmerged panel is
  ##   written too (*_allterms). Enrichment p-values are unchanged; this only
  ##   chooses which terms are drawn.
  ##   The heatmap is drawn directly rather than with enrichplot::heatplot:
  ##   page width (7.2 in), pathways ordered by adjusted p with a -log10 p bar
  ##   beside each row, genes grouped by the first drawn pathway they belong to,
  ##   sequential pastel -> red fill (all genes are up), no burned-in title.
  if (!exists("theme_astro_pub"))
    source(file.path(SCORCH_REPO, "revision/tools/astro_pub_theme.R"))
  ego_simpl <- clusterProfiler::simplify(ego, cutoff = 0.6, by = "p.adjust",
                                         select_fun = min, measure = "Wang")
  n_wang <- nrow(as.data.frame(ego_simpl))
  ## Second pass, gene-set overlap: Wang similarity leaves three GBP1/GBP2-driven
  ##   "killing of / disruption of cell / anatomical structure in another
  ##   organism" terms and locomotion vs cell motility. A term is dropped when it
  ##   shares >= half of its genes (Jaccard >= 0.5) with a more significant term
  ##   already kept.
  r  <- ego_simpl@result[order(ego_simpl@result$p.adjust), ]
  gs <- strsplit(r$geneID, "/", fixed = TRUE)
  keep <- logical(nrow(r))
  for (i in seq_len(nrow(r)))
    keep[i] <- !any(vapply(which(keep), function(j)
      length(intersect(gs[[i]], gs[[j]])) / length(union(gs[[i]], gs[[j]])), numeric(1)) >= 0.5)
  ego_simpl@result <- r[keep, ]
  message("[Fig1E] simplify: ", nrow(as.data.frame(ego)), " terms -> ", n_wang,
          " (Wang > 0.6) -> ", nrow(as.data.frame(ego_simpl)), " (gene overlap < 0.5)")
  ## written AFTER both passes, so the table matches the drawn term list
  utils::write.csv(as.data.frame(ego_simpl), file.path(ASTRO_FIG_DIR(), "tables",
                   paste0("Fig1E_GO_Reactive_PWH_simplified", SFX, ".csv")), row.names = FALSE)
  ## reactive-astrocyte markers (shown in the published panel): always drawn when
  ##   they belong to a drawn term - thinning to 40 genes otherwise cuts them
  ##   (paired test ranks: CHI3L1 149, OSMR 223, SERPINA3 362 of 903)
  FIG1E_MARKERS <- c("SERPINA3", "OSMR", "CHI3L1")

  draw_fig1e <- function(e, stub) {
    ## Enrichment is computed on all the up genes; only the display is thinned.
    ## display genes = the N_SHOW with the largest fold change among the genes in
    ##   the drawn terms. All of them already pass FDR < 0.05 and log2FC > 0.5.
    in_terms   <- genes_in_top_terms(e, n_terms = N_TERMS)
    d_in       <- sde$de[sde$de$gene %in% in_terms, ]
    show_genes <- utils::head(d_in$gene[order(-d_in$logFC)], N_SHOW)
    forced     <- setdiff(intersect(FIG1E_MARKERS, in_terms), show_genes)
    show_genes <- c(show_genes, forced)
    message("[Fig1E] ", stub, ": markers in drawn terms: ",
            paste(intersect(FIG1E_MARKERS, in_terms), collapse = ", "),
            " (added beyond the top ", N_SHOW, ": ", if (length(forced)) paste(forced, collapse = ", ") else "none",
            "); not in any drawn term: ", paste(setdiff(FIG1E_MARKERS, in_terms), collapse = ", "))
    tr <- trim_enrich(e, show_genes, n_terms = N_TERMS)@result
    tr <- tr[order(tr$p.adjust), ]
    long <- do.call(rbind, lapply(seq_len(nrow(tr)), function(i)
      data.frame(term = tr$Description[i], gene = strsplit(tr$geneID[i], "/", fixed = TRUE)[[1]],
                 stringsAsFactors = FALSE)))
    long$logFC <- sde$de$logFC[match(long$gene, sde$de$gene)]
    ## genes grouped by the FIRST (most significant) drawn term they belong to,
    ## then by effect size - block structure down the diagonal
    first <- tapply(match(long$term, tr$Description), long$gene, min)
    lfc   <- tapply(long$logFC, long$gene, max)
    gene_order <- names(first)[order(first, -lfc[names(first)])]
    wrap <- function(x) vapply(x, function(s) paste(strwrap(s, 34), collapse = "\n"), character(1))
    term_lv <- rev(wrap(tr$Description))          # most significant on top
    long$term <- factor(wrap(long$term), levels = term_lv)
    long$gene <- factor(long$gene, levels = gene_order)
    bars <- data.frame(term = factor(wrap(tr$Description), levels = term_lv),
                       mlp = -log10(tr$p.adjust))

    p_hm <- ggplot(long, aes(x = gene, y = term, fill = logFC)) +
      geom_tile(colour = "white", linewidth = 0.35) +
      scale_fill_gradient(low = "#FCDCCF", high = "#B2182B",
                          name = "log2 FC\n(Reactive-PWH vs\nother astrocytes)") +
      scale_x_discrete(expand = c(0, 0)) + scale_y_discrete(expand = c(0, 0)) +
      labs(x = NULL, y = NULL) +
      theme_astro_pub(base_size = 7) +
      theme(axis.line = element_blank(), axis.ticks = element_blank(),
            axis.text.x = element_text(angle = 90, hjust = 1, vjust = 0.5, size = 6.3, face = "italic"),
            axis.text.y = element_text(size = 7.3, lineheight = 0.85),
            panel.border = element_rect(colour = "grey40", fill = NA, linewidth = 0.3),
            legend.position = "right", legend.key.height = unit(0.45, "cm"),
            legend.key.width = unit(0.25, "cm"), legend.title = element_text(size = 6.5))
    p_bar <- ggplot(bars, aes(x = mlp, y = term)) +
      geom_col(fill = "grey55", width = 0.6) +
      scale_x_continuous(expand = expansion(mult = c(0, 0.08)), n.breaks = 3) +
      labs(x = expression(-log[10]~adj.~p), y = NULL) +
      theme_astro_pub(base_size = 7) +
      theme(axis.text.y = element_blank(), axis.ticks.y = element_blank(),
            axis.line.y = element_blank(), axis.title.x = element_text(size = 6.5))
    p <- p_hm + p_bar + plot_layout(widths = c(1, 0.12), guides = "collect")
    f <- file.path(ASTRO_FIG_DIR(), paste0(stub, SFX, ".png"))
    save_pub(p, f, width = 7.2, height = 1.1 + 0.26 * nrow(tr))
    astro_caption(f, paste0(
      "GO biological processes enriched among genes up in Reactive-PWH astrocytes (donor-paired ",
      "pseudobulk: each donor's Reactive-PWH nuclei vs their remaining astrocytes, edgeR QL, ",
      length(unique(sde$donors$donor[sde$donors$usable])), " donors; FDR < 0.05, log2 FC > ",
      FIG1E_LFC, ", n = ", length(gene), " genes). Background: the ", length(universe),
      " genes tested. Near-duplicate terms merged (Wang semantic similarity > 0.6, then gene ",
      "overlap Jaccard >= 0.5, keeping the more significant term)",
      if (grepl("allterms", stub)) " - NOT applied in this version" else "",
      ". Top ", nrow(tr), " terms by adjusted p; tiles show the ", N_SHOW,
      " marker genes with the largest fold change in those terms, plus the reactive-astrocyte markers ",
      "SERPINA3, OSMR and CHI3L1 where they belong to a drawn term, coloured by log2 ",
      "fold change; bars, -log10 adjusted p."))
    message("[Fig1E] ", stub, ": ", nrow(tr), " pathways, ", length(show_genes), " genes drawn")
  }
  draw_fig1e(ego_simpl, "Fig1E_GO_heatmap_Reactive_PWH")
  draw_fig1e(ego, "Fig1E_GO_heatmap_Reactive_PWH_allterms")
  ran <- c(ran, "Fig1E")
}, error = function(e) { message("[astro-ms] Fig1E FAILED: ", conditionMessage(e))
                         skipped <<- c(skipped, "Fig1E (error)") })

## ---- S12b: subtype proportion by donor ---------------------------------------
if (want("S12b")) tryCatch({
  message("\n=================== S12b ===================")
  metadata <- clean_scorch_astro@meta.data %>%
    group_by(sample_ids, subcluster_labels, condition_new) %>%
    summarise(count = dplyr::n(), .groups = "drop") %>%
    group_by(subcluster_labels) %>%
    mutate(proportion = count / sum(count) * 100) %>%
    ungroup()

  ## REVISION (Rmd:647): hand-built CTR-blue / HIV-pink-red ramps replaced; the
  ## PWH ramp is orange to match PWH_COLOURS, donor ordering deterministic.
  color_map <- donor_condition_palette(metadata$sample_ids, metadata$condition_new)

  ## REVISION (reviewer request): condition was encoded only as a blue vs orange
  ##   ramp over 33 look-alike sample IDs. Each legend entry names its condition,
  ##   and the entries are grouped PWoH first, then PWH.
  .cond <- metadata %>%
    dplyr::distinct(sample_ids, condition_new) %>%
    dplyr::mutate(cond = factor(as.character(pwh_relabel(condition_new)), levels = PWH_LEVELS)) %>%
    dplyr::arrange(cond, sample_ids)
  .lab <- setNames(paste0(.cond$sample_ids, "  \u00b7  ", as.character(.cond$cond)),
                   as.character(.cond$sample_ids))
  metadata$sample_lab <- factor(.lab[as.character(metadata$sample_ids)], levels = unname(.lab))
  color_map <- setNames(color_map[as.character(.cond$sample_ids)], unname(.lab))

  p <- ggplot(metadata, aes(x = subcluster_labels, y = proportion, fill = sample_lab)) +
    geom_bar(stat = "identity", position = "stack", color = "black") +
    scale_fill_manual(values = color_map) +
    theme_minimal(base_size = 14) +
    theme(panel.grid = element_blank(),
          axis.text.x = element_text(angle = 45, hjust = 1, vjust = 1, size = 12),
          axis.text.y = element_text(size = 12),
          axis.title.x = element_text(size = 16, face = "bold"),
          axis.title.y = element_text(size = 16, face = "bold"),
          plot.title = element_text(size = 18, face = "bold", hjust = 0.5),
          legend.text = element_text(size = 12),
          legend.title = element_text(size = 14, face = "bold")) +
    labs(x = "Astrocyte Subtype", y = "Proportion (%)", fill = "Sample (condition)",
         title = "Sample Proportions of Astrocyte Subtype") +
    guides(fill = guide_legend(ncol = 2, byrow = FALSE))

  sfig(p, "S12b_subtype_proportion_by_donor", width = 12, height = 7)
  ran <- c(ran, "S12b")
}, error = function(e) { message("[astro-ms] S12b FAILED: ", conditionMessage(e))
                         skipped <<- c(skipped, "S12b (error)") })

## ---- S13a: inflammatory dot plot ---------------------------------------------
if (want("S13a")) tryCatch({
  message("\n=================== S13a ===================")
  ## Colour by condition as in the paper. With split.by, DotPlot gives each split
  ##   level its own grey-to-colour ramp, taken from `cols` in factor-level order -
  ##   so the factor fixes PWoH first and the colours follow PWH_COLOURS (PWoH
  ##   blue, PWH orange), the palette of every condition label.
  clean_scorch_astro$condition_updated <-
    factor(as.character(pwh_relabel(clean_scorch_astro$condition_new)), levels = PWH_LEVELS)
  p <- DotPlot(clean_scorch_astro,
               features = c("IL1B","IL6","IL6R","IL1R1","C3"),
               split.by = "condition_updated",
               cols = unname(PWH_COLOURS[PWH_LEVELS]))
  ## 5 genes on the x axis: 7 in wide still fits the two condition colour keys
  sfig(p, "S13a_inflammatory_dotplot", width = 7, height = 6)
  ran <- c(ran, "S13a")
}, error = function(e) { message("[astro-ms] S13a FAILED: ", conditionMessage(e))
                         skipped <<- c(skipped, "S13a (error)") })

## ---- S12a: astrocyte percentage by region (needs scorch_meta) ----------------
if (want("S12a")) {
  message("\n=================== S12a ===================")
  mp <- file.path(OUT_ROOT, "01-Regional_data_processing", "combined", "data",
                  "combined_v3_cell_metadata.csv")
  if (!file.exists(mp)) {
    message("[astro-ms] S12a SKIPPED - missing ", basename(mp),
            "\n  run: revision/docker/run.sh revision/tools/dump_combined_metadata.R",
            "\n  and make sure it dumps from the 1040-FILTERED combined object")
    skipped <- c(skipped, "S12a (no scorch_meta)")
  } else tryCatch({
    scorch_meta <- utils::read.csv(mp, row.names = 1, stringsAsFactors = FALSE)
    message("[astro-ms] scorch_meta: ", nrow(scorch_meta), " cells")

    ## Guard: match donor 1040's VST cells on sample_name alone ("1040_HIV_VST")
    ##   and stop rather than warn, so a _no1040vst figure can never be drawn from
    ##   metadata that still holds those cells.
    .n1040 <- sum(grepl("^1040_.*_VST$", as.character(scorch_meta$sample_name)))
    message("[astro-ms] donor 1040 VST cells in scorch_meta: ", .n1040)
    if (.n1040 > 0 && nzchar(SFX))
      stop("scorch_meta still has ", .n1040, " of donor 1040's VST cells, but ",
           "the output suffix is '", SFX, "'. Re-dump it first:\n",
           "  revision/docker/run.sh revision/tools/dump_combined_metadata.R")

    astro_plot_data <- scorch_meta %>%
      dplyr::mutate(region = dplyr::case_when(
        grepl("_INS$", sample_name) ~ "INS",
        grepl("_PFC$", sample_name) ~ "PFC",
        grepl("_VST$", sample_name) ~ "VST",
        TRUE ~ "Unknown")) %>%
      ## REVISION: the notebook set comparisons = list(c("PWoH","PWH")) while
      ## condition_new holds "CTR"/"HIV" and the fill scale was keyed to
      ## CTR/HIV, so stat_compare_means() matched nothing and drew no p-value.
      ## Relabel once, up front, so the fill, the axis and the test all agree.
      dplyr::mutate(condition_lab = as.character(pwh_relabel(condition_new))) %>%
      dplyr::group_by(sample_name, region, condition_lab) %>%
      dplyr::summarize(total_cells = dplyr::n(),
                       astro_cells = sum(consensus_annotation_v3 == "Astro"),
                       astro_percentage = (astro_cells / total_cells) * 100,
                       .groups = "drop")
    astro_plot_data$condition_lab <- factor(astro_plot_data$condition_lab,
                                            levels = PWH_LEVELS)

    p <- ggplot(astro_plot_data,
                aes(x = condition_lab, y = astro_percentage, fill = condition_lab)) +
      geom_violin(trim = TRUE, alpha = 0.6, position = position_dodge(0.8)) +
      geom_jitter(size = 2, alpha = 0.8, position = position_dodge(0.8)) +
      scale_fill_manual(values = PWH_COLOURS) +
      stat_compare_means(comparisons = list(PWH_LEVELS), method = "t.test",
                         label = "p.format") +
      facet_wrap(~region, scales = "free_y") +
      labs(title = "Abundance of Astrocytes by Region and Condition",
           x = "Condition", y = "Astrocyte Cell Percentage (%)") +
      theme_minimal(base_size = 14) +
      theme(axis.text.x = element_text(angle = 45, hjust = 1, face = "bold"),
            axis.text.y = element_text(face = "bold"),
            axis.title.x = element_text(face = "bold", size = 14),
            axis.title.y = element_text(face = "bold", size = 14),
            strip.text = element_text(face = "bold", size = 12),
            plot.title = element_text(face = "bold", size = 16, hjust = 0.5),
            legend.position = "none",
            panel.grid.major = element_line(color = "gray80", linetype = "dotted"))

    sfig(p, "S12a_astro_percentage_by_region", width = 11, height = 6)
    ran <- c(ran, "S12a")
  }, error = function(e) { message("[astro-ms] S12a FAILED: ", conditionMessage(e))
                           skipped <<- c(skipped, "S12a (error)") })
}

## ---- cross-region DE inputs for Fig1B and S15 --------------------------------
## Rmd:238. The cross-region table from xr_de_file(), donor 1040 excluded from VST:
## edgeR QL with the negative-F fallback by default, or the donor-aware limma-voom +
## duplicateCorrelation (block = donor) table, the primary model, under
## SCORCH_XR_DE=donor_aware.
if (want("Fig1B") || want("S15")) {
  inp <- astro_figure_inputs(source_de = "cross_region", counts = "uncorrected")
  de_edgeR    <- inp$de_edgeR
  genes       <- inp$genes
  deg_results <- inp$deg_results
  message("[astro-ms] cross-region DE: ", inp$de_path)
}

## --s15-de subtype (S15 as PWH vs PWoH within each astrocyte subtype): feed the
##   S15 heatmaps the donor-aware within-subtype DE of
##   revision/tools/astro_subtype_condition_de.R instead of the per-cell-type cross-region DE.
##   Same FindMarkers-style mapping as deg_results_from_de: p_val_adj = p_adj.glb,
##   avg_log2FC = logFC, pct.1 = fraction of the subtype's PWH nuclei detected.
S15_DE <- match.arg(getarg("--s15-de", "celltype"), c("celltype", "subtype"))
S15_PREFIX <- if (S15_DE == "subtype") "S15sub_pathway_" else "S15_pathway_"
if (want("S15") && S15_DE == "subtype") {
  .sub <- utils::read.csv(file.path(OUT_ROOT, "06-astrocyte_analysis", "subtype_condition_de",
                                    "astro_subtype_PWH_vs_PWoH.csv"), stringsAsFactors = FALSE)
  deg_results <- lapply(split(.sub, .sub$cluster_id), function(d)
    data.frame(row.names = d$gene, p_val = d$p_val, avg_log2FC = d$logFC,
               pct.1 = d$pct_PWH, pct.2 = d$pct_PWoH, p_val_adj = d$p_adj.glb))
  deg_results <- deg_results[intersect(c("Homeostatic", "Reactive", "Signaling", "Synaptic"),
                                       names(deg_results))]
  message("[astro-ms] S15 from within-subtype PWH vs PWoH DE: ", paste(names(deg_results), collapse = ", "))
}
TAB_DIR <- file.path(ASTRO_FIG_DIR(), "tables")
dir.create(TAB_DIR, recursive = TRUE, showWarnings = FALSE)
tab <- function(x, name) utils::write.csv(x, file.path(TAB_DIR, paste0(name, SFX, ".csv")),
                                          row.names = FALSE)

## ---- Fig1B: GO enrichment, PWH and PWoH astrocytes (Rmd:262-405) -------------
if (want("Fig1B")) tryCatch({
  message("\n=================== Fig1B ===================")
  fig1b_theme <- theme(
    plot.title = element_text(size = 16, face = "bold", hjust = 0.5),
    axis.text.x = element_text(size = 14, face = "bold"),
    axis.line.x = element_line(color = "black"),
    axis.line.y = element_line(color = "black"),
    panel.grid.major.x = element_line(color = "gray90", linetype = "dashed"),
    panel.grid.major.y = element_blank(),
    axis.text.y = element_blank(),
    axis.ticks.y = element_blank(),
    plot.margin = margin(t = 20, r = 20, b = 20, l = 20))

  ## PWoH: genes down in PWH
  top_edgeR_pwoh <- de_edgeR %>%
    dplyr::filter((avg_CTR_frq > 0.05) | (avg_HIV_frq > 0.05)) %>%
    dplyr::select(gene, cluster_id, logFC, logCPM, p_adj.glb) %>%
    dplyr::filter((logFC < -0.25) & (p_adj.glb < 0.05), cluster_id == "Astro")

  ## PWH: genes up in PWH
  ## REVISION (Rmd:333): the published `logFC < 0.25` selected everything below
  ##   +0.25, including every PWoH gene, so the two panels were near-identical by
  ##   construction. Genes up in PWH are logFC > 0.25.
  top_edgeR_pwh <- de_edgeR %>%
    dplyr::filter((avg_CTR_frq > 0.05) | (avg_HIV_frq > 0.05)) %>%
    dplyr::select(gene, cluster_id, logFC, logCPM, p_adj.glb) %>%
    dplyr::filter((logFC > 0.25) & (p_adj.glb < 0.05), cluster_id == "Astro")
  message(sprintf("[Fig1B] Astro genes into enrichGO: PWoH (down) %d, PWH (up) %d, overlap %d",
                  nrow(top_edgeR_pwoh), nrow(top_edgeR_pwh),
                  length(intersect(top_edgeR_pwoh$gene, top_edgeR_pwh$gene))))

  go_bp <- function(g) enrichGO(gene = g, keyType = "SYMBOL", OrgDb = org.Hs.eg.db,
                                universe = genes, ont = "BP", pAdjustMethod = "BH",
                                pvalueCutoff = 0.05, qvalueCutoff = 0.05, readable = TRUE)

  ## REVISION (Rmd:365): the published PWH branch piped the enrichResult object
  ##   rather than its data frame; both branches take the data frame.
  top10 <- function(ego) ego@result %>%
    mutate(logP = -log10(p.adjust)) %>%
    arrange(desc(logP)) %>%
    slice_head(n = 10)

  ego_pwoh_df <- top10(go_bp(top_edgeR_pwoh$gene))
  ego_pwh_df  <- top10(go_bp(top_edgeR_pwh$gene))
  tab(ego_pwoh_df, "Fig1B_GO_PWoH_astrocytes_top10")
  tab(ego_pwh_df,  "Fig1B_GO_PWH_astrocytes_top10")
  message("[Fig1B] PWoH top term: ", ego_pwoh_df$Description[1],
          " (p.adjust ", signif(ego_pwoh_df$p.adjust[1], 3), ")")
  message("[Fig1B] PWH  top term: ", ego_pwh_df$Description[1],
          " (p.adjust ", signif(ego_pwh_df$p.adjust[1], 3), ")")

  p_fig1b_pwoh <- ggplot(ego_pwoh_df, aes(x = logP, y = reorder(Description, logP))) +
    geom_bar(stat = "identity", fill = "#CCE5FF", width = 0.7) +
    geom_text(aes(x = 0.5, label = Description), hjust = 0, color = "black",
              size = 8, fontface = "italic") +
    theme_minimal(base_size = 15) +
    labs(x = "-log10(p.adjust)", y = NULL, title = "Top 10 Enriched GO Terms in PWoH Astrocytes") +
    fig1b_theme

  p_fig1b_pwh <- ggplot(ego_pwh_df, aes(x = logP, y = reorder(Description, logP))) +
    geom_bar(stat = "identity", fill = "#FFEDD5", width = 0.7) +
    geom_text(aes(x = 0.1, label = Description), hjust = 0, color = "black",
              size = 8, fontface = "italic") +
    theme_minimal(base_size = 15) +
    labs(x = "-log10(p.adjust)", y = NULL, title = "Top 10 Enriched GO Terms in PWH Astrocytes") +
    fig1b_theme

  sfig(p_fig1b_pwoh, "Fig1B_GO_PWoH_astrocytes", width = 10, height = 7)
  sfig(p_fig1b_pwh,  "Fig1B_GO_PWH_astrocytes",  width = 10, height = 7)
  ran <- c(ran, "Fig1B")
}, error = function(e) { message("[astro-ms] Fig1B FAILED: ", conditionMessage(e))
                         skipped <<- c(skipped, "Fig1B (error)") })

## ---- S15: per-cell-type GO heatmaps, down and up (Rmd:747-908) ---------------
## deg_results has FindMarkers column names but donor-level numbers underneath
## (deg_results_from_de): p_val_adj = p_adj.glb, avg_log2FC = logFC,
## pct.1 = avg_HIV_frq. The loop body is the notebook's, unchanged.
s15_heatmaps <- function(direction) {
  heatmap_list <- list()   # REVISION (Rmd:828): reset between the two loops
  kept <- list()
  for (cell in names(deg_results)) {
    degs <- deg_results[[cell]]
    degs$Gene <- rownames(degs)
    degs <- if (direction == "down")
      degs %>% filter(p_val_adj < 0.05, avg_log2FC < -0.5, pct.1 > 0.05)
    else
      ## REVISION (Rmd:838): the published `avg_log2FC < 0.5` also selected every
      ##   down gene. Genes up are avg_log2FC > 0.5.
      degs %>% filter(p_val_adj < 0.05, avg_log2FC > 0.5, pct.1 > 0.05)

    geneList <- degs$avg_log2FC
    names(geneList) <- degs$Gene
    if (length(geneList) <= 10) {
      message("[S15] ", direction, " ", cell, ": ", length(geneList),
              " genes - not enough for enrichment, skipped")
      next
    }
    pathway_test <- tryCatch(
      enrichGO(gene = names(geneList), keyType = "SYMBOL", OrgDb = org.Hs.eg.db,
               ont = "BP", pAdjustMethod = "BH", pvalueCutoff = 0.01,
               qvalueCutoff = 0.05, readable = TRUE),
      error = function(e) NULL)
    if (is.null(pathway_test) || nrow(as.data.frame(pathway_test@result)) == 0) {
      message("[S15] ", direction, " ", cell, ": ", length(geneList),
              " genes - no significant pathways, skipped")
      next
    }
    pathway_df <- as.data.frame(pathway_test@result) %>%
      arrange(p.adjust) %>%
      slice_head(n = 5) %>%
      dplyr::select(Description, geneID) %>%
      separate_rows(geneID, sep = "/") %>%
      inner_join(degs, by = c("geneID" = "Gene")) %>%
      group_by(Description) %>%
      top_n(10, wt = abs(avg_log2FC))
    pathway_df$geneID <- factor(pathway_df$geneID, levels = unique(pathway_df$geneID))
    pathway_df$Description <- factor(pathway_df$Description, levels = rev(unique(pathway_df$Description)))

    heatmap_list[[cell]] <- ggplot(pathway_df, aes(x = geneID, y = Description, fill = avg_log2FC)) +
      geom_tile(color = "white") +
      scale_fill_gradient2(low = "blue", mid = "white", high = "red", midpoint = 0) +
      theme_minimal(base_size = 14) +
      theme(axis.text.x = element_text(angle = 45, hjust = 1, size = 12, color = "black"),
            axis.text.y = element_text(size = 12, color = "black"),
            axis.title.x = element_text(size = 14, color = "black"),
            axis.title.y = element_text(size = 14, color = "black"),
            panel.grid.major = element_blank(),
            panel.grid.minor = element_blank()) +
      labs(title = paste(if (direction == "down") "GO Enrichment (Downregulated) -"
                         else "GO Enrichment (Upregulated) -", cell),
           x = "geneID", y = "Pathway", fill = "Log2FC")
    kept[[cell]] <- data.frame(cell_type = cell, n_genes = length(geneList),
                               as.data.frame(pathway_df), check.names = FALSE)
    message("[S15] ", direction, " ", cell, ": ", length(geneList), " genes, ",
            nlevels(pathway_df$Description), " pathways drawn")
  }
  for (cell in names(heatmap_list))
    sfig(heatmap_list[[cell]], paste0(S15_PREFIX, direction, "_", cell), width = 11, height = 7)
  if (length(kept)) tab(dplyr::bind_rows(kept), paste0(S15_PREFIX, direction, "_plotted"))
  names(heatmap_list)
}

if (want("S15")) tryCatch({
  message("\n=================== S15 ===================")
  s15_down <- s15_heatmaps("down")
  s15_up   <- s15_heatmaps("up")
  message("[S15] down panels: ", paste(s15_down, collapse = ", "))
  message("[S15] up panels  : ", paste(s15_up, collapse = ", "))
  ran <- c(ran, "S15")
}, error = function(e) { message("[astro-ms] S15 FAILED: ", conditionMessage(e))
                         skipped <<- c(skipped, "S15 (error)") })

message("\n########## SUMMARY ##########")
message("produced: ", if (length(ran)) paste(ran, collapse = ", ") else "(none)")
message("skipped : ", if (length(skipped)) paste(skipped, collapse = ", ") else "(none)")
message("\nfigures in ", file.path(OUT_ROOT, "06-astrocyte_analysis", "figures"))
